/** A tree root: every node is either a leaf carrying a size or a group carrying children. */
export type Data = { name: string; value?: number; children?: Data[] };

type Circle = d3.HierarchyCircularNode<Data>;

const MAX_SIDE = 640;
const PADDING = 3;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels wider than their circle. */
const CHAR_WIDTH = 5.6;
const MIN_LABEL_RADIUS = 14;

const format = d3.format(',d');

function pathOf(node: Circle): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join('/');
}

/** Pale fills need dark ink, dark fills need light ink. */
function inkFor(fill: string): string {
  return d3.lab(fill).l > 62 ? '#20180a' : '#f5ecd8';
}

export default function Pack({ data = assetTree, width }: { data?: Data; width: number }) {
  // Floored because hooks cannot be skipped: the width === 0 bail below runs after this memo,
  // and d3.pack throws rather than degrading when handed a zero-sized box.
  const side = Math.max(1, Math.min(width, MAX_SIDE));

  const root = useMemo(
    () =>
      d3
        .pack<Data>()
        .size([side, side])
        .padding(PADDING)(
          d3
            .hierarchy(data)
            .sum((d) => d.value ?? 0)
            .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))
        ),
    [data, side]
  );

  const leafColor = useMemo(() => {
    const values = root.leaves().map((d) => d.value ?? 0);
    return d3
      .scaleSequential(d3.interpolateHcl('#4a3a18', '#e8c37a'))
      .domain([d3.min(values) ?? 0, d3.max(values) ?? 1]);
  }, [root]);

  if (width === 0) return null;

  const nodes = root.descendants().slice(1);
  const labeled = nodes.filter((d) => !d.children && d.r > MIN_LABEL_RADIUS);

  return (
    <svg
      viewBox={`0 0 ${side} ${side}`}
      width="100%"
      height={side}
      role="img"
      aria-label="Circle packing of a static-site asset tree, sized by kilobytes, with folders as open rings around their files"
      style={{ display: 'block', font: `${FONT_SIZE}px sans-serif` }}
    >
      {nodes.map((d) =>
        d.children ? (
          <circle
            key={pathOf(d)}
            cx={d.x}
            cy={d.y}
            r={d.r}
            fill="none"
            stroke="var(--line)"
          />
        ) : (
          <circle
            key={pathOf(d)}
            cx={d.x}
            cy={d.y}
            r={d.r}
            fill={leafColor(d.value ?? 0)}
          >
            <title>{`${pathOf(d)}\n${format(d.value ?? 0)} KB`}</title>
          </circle>
        )
      )}
      {labeled.map((d) => {
        const words = d.data.name.split(/(?=[A-Z][a-z])|[-_.]|\s+/g).filter(Boolean);
        const ink = inkFor(leafColor(d.value ?? 0) as string);
        return (
          <text
            key={pathOf(d)}
            x={d.x}
            y={d.y}
            textAnchor="middle"
            fill={ink}
            clipPath={`circle(${d.r}px)`}
          >
            {words.map((word, i) => (
              <tspan key={i} x={d.x} dy={`${i - words.length / 2 + 0.35}em`}>
                {word}
              </tspan>
            ))}
            <tspan x={d.x} dy={`${words.length / 2 + 0.35}em`} fillOpacity={0.7}>
              {format(d.value ?? 0)}
            </tspan>
          </text>
        );
      })}
    </svg>
  );
}
